async def seed():
    client = AsyncIOMotorClient(settings.MONGODB_URL)
    db = client[settings.DATABASE_NAME]
    print(f"Connected to MongoDB: {settings.DATABASE_NAME}")

    now = datetime.utcnow()
    for m in medicines:
        m["created_at"] = now
        m["updated_at"] = now
        m["is_active"] = True
    for k in kendras:
        k["created_at"] = now
        k["updated_at"] = now
        k["is_active"] = True

    await db["medicines"].delete_many({})
    await db["kendras"].delete_many({})
    print("Cleared old data")

    result1 = await db["medicines"].insert_many(medicines)
    print(f"Real medicines seeded: {len(result1.inserted_ids)}")

    result2 = await db["kendras"].insert_many(kendras)
    print(f"Real Mysuru Kendras seeded: {len(result2.inserted_ids)}")

    client.close()
    print("Done! Your database now has real Jan Aushadhi data.")


if __name__ == "__main__":
    asyncio.run(seed())